# audit/matrix/hints.ps1
# Where to look when a check does not pass. Printed in the report's "Next steps" section.

$Hints = @{
    "S1"    = "The backend is not reachable. Rig: docker compose logs backend. Tunnel mode: confirm ngrok forwards to the right port."
    "S2"    = "Login worked but /me rejected the session. Check the cookie jar domain/path and the auth middleware."
    "S3"    = "No CSRF cookie after login. Confirm -CsrfCookie and -CsrfHeader against the CSRF middleware (csrfConfig)."
    "S5"    = "The Paystack stub answers 'success' for a reference nobody paid. Fix the stub so unpaid references verify as 'abandoned' or 'pending'. Every T9 result is meaningless until then."
    "S6"    = "Same as S5, for a reference the backend has just initialised."
    "S7"    = "InitiateSubscription builds callback_url from FRONTEND_URL. If only FRONTEND_BASE_URL is set the callback is relative. Decide on one variable name and use it everywhere."
    "T13.1" = "Public prices differ from the server table. Check GetPlans and monthlyPriceKobo."
    "T12.1" = "Initiate answered without a session. The auth middleware is not applied to this route."
    "T12.2" = "Verify answered without a session. The auth middleware is not applied to this route."
    "T12.3" = "Initiate accepted a session without a CSRF token (or -CsrfHeader is wrong). Check CSRFProtection on the subscription group."
    "T10.1" = "A bad tier was not rejected with 400, or a ledger row was written. Check PriceKobo validation order in InitiateSubscription."
    "T10.2" = "The request body influenced which vendor was charged. The vendor must come only from ExtractVendorID."
    "T9.1"  = "Initiate failed. Check S3 (CSRF), the backend log, and that the backend can reach its Paystack base URL."
    "T9.2"  = "Ledger row missing or wrong. Check CreatePayment, that backend and AUDIT_DB_URL use the same database, and that migration 000001 is applied there."
    "T9.3"  = "A subscription row was created at initiate. An old pending-row code path is still active."
    "T9.4"  = "Verify did not refuse an unpaid reference. A 200 means the activation hole is back: settle() must require data.status == success. A 500 usually means the gateway answered 'not found': map ErrTransactionNotFound to ErrPaymentNotSuccessful."
    "T9.5"  = "Verify changed state for an unpaid reference. Stop and inspect settle() and SettlePayment."
    "T9b.1" = "A permanent failure was not acknowledged with 200. Check IsRetryable and the dispatcher's error branch."
    "T9b.2" = "A webhook that merely claims success changed state or was not counted. The server must re-verify with the gateway and count attempts on the ledger."
    "T3.1"  = "A forged signature was not rejected with 401. Check VerifyWebhookSignature in HandlePaystackWebhook."
    "T3.2"  = "A missing signature was not rejected with 401. Check the dispatcher's signature handling."
    "T3.3"  = "A signature over a different body was accepted or counted. The HMAC must cover the exact raw body, and counting must come after verification."
    "T3c.1" = "A webhook for an unknown reference was not acknowledged cleanly, or created rows. Check the not-found branch in HandleWebhook."
    "T8.1"  = "Another vendor could reach this payment. Check the ownership comparison in VerifyAndFinalize (and that unknown references look identical)."
    "T16.1" = "The webhook body is read in full before the signature check. Add http.MaxBytesReader to the dispatcher."
    "T17.1" = "A hostile reference produced a non-4xx response. Check input handling and error mapping in the verify handler."
    "T7.1"  = "Tier switching while active is not blocked. Check the R2 rule in InitiateSubscription."
    "T15.1" = "No rate limiting observed. Every initiate wrote a ledger row and called the gateway; consider a per-vendor limit on initiate."
    "T1.2"  = "Paystack never delivered the webhook. The dashboard webhook URL is not the tunnel URL, or the tunnel was down."
    "T1.4"  = "Expiry did not move by about a month. Check NextExpiry and SettlePayment, and the time-zone note F19."
    "T5.1"  = "An amount mismatch was not parked for review. Check the comparison in SettlePayment."
}